package scan

import (
	"bufio"
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"log"
	"os"
	"path"
	"path/filepath"
	"regexp"
	"strings"

	"gopkg.in/yaml.v3"

	"github.com/anthnel/devdesk/internal/k8s"
)

// A Helm chart or a Kustomize overlay is validated after it is rendered
// (§3.80). Both renderers are optional: without them the directory is
// reported as not rendered, never as clean, and never as a missing tool —
// the schema stage did all it could.
//
// Measured on helm v4.3.0's sources (pkg/cmd/lint.go and
// pkg/chart/v2/lint/support/message.go) and kustomize v5.8.1's Dockerfile:
// alpine/helm's entrypoint is `helm`, the kustomize image's is
// /app/kustomize, so in both the arguments follow the image name.

// Default images for the two renderers.
const (
	DefaultHelmImage      = "alpine/helm"
	DefaultKustomizeImage = "registry.k8s.io/kustomize/kustomize:v5.8.1"
)

// IDs of the findings the renderers themselves produce.
const (
	// HelmLintID is a message helm lint reported, at WARNING or ERROR.
	HelmLintID = "HELM-LINT"
	// K8sRenderID is a chart or an overlay that did not render at all.
	K8sRenderID = "K8S-RENDER"
)

// helmLintLine is one message of helm lint: `[SEVERITY] path: message`, as
// support.Message.Error formats it.
var helmLintLine = regexp.MustCompile(`^\[(ERROR|WARNING|INFO|UNKNOWN)\] ([^:]*): (.*)$`)

// helmSourceLine is the comment helm template writes above each document,
// naming the template it came from: `# Source: <chart name>/templates/x.yaml`.
var helmSourceLine = regexp.MustCompile(`^# Source: (\S+)`)

// renderScope is where a renderer runs. A binary runs in the target and sees
// the whole host. A container sees only mount, read-only at /scan, and works in
// the target inside it: mount is the target itself, or the git repository
// holding it, so an overlay or a chart can reach a sibling of the target as it
// does on the host (DEVDESK-742).
type renderScope struct {
	target string
	mount  string
	// rel is the target relative to mount, with forward slashes; "" when the
	// target is what is mounted.
	rel string
}

// targetOnly mounts the target and nothing else.
func targetOnly(target string) renderScope { return renderScope{target: target, mount: target} }

// workdir is the target inside the container.
func (s renderScope) workdir() string { return path.Join(containerScanPath, s.rel) }

// userHomeDir is the home directory the mount guard keeps out of reach. Tests
// swap it.
var userHomeDir = os.UserHomeDir

// resolveRenderScope asks git, in the target, for the repository holding it.
// Without an answer (no git, not a repository), or when the repository's
// configuration moves its work tree elsewhere (core.worktree, which a cloned
// .git file can bring along), the target alone is mounted.
func resolveRenderScope(ctx context.Context, target string) renderScope {
	git := func(args ...string) ([]byte, error) {
		return runner.Run(ctx, toolCmd{Name: "git", Args: args, Dir: target, Env: gitEnviron(os.Environ())}, nil)
	}
	out, err := git("rev-parse", "--show-toplevel")
	if err != nil {
		log.Printf("[scan/k8s] %s: no git repository to mount, the renderers see the target only: %v", target, err)
		return targetOnly(target)
	}
	worktree, err := git("config", "--get", "core.worktree")
	var exitErr *exitError
	unset := errors.As(err, &exitErr) && exitErr.Code == 1 && len(bytes.TrimSpace(worktree)) == 0
	if !unset {
		log.Printf("[scan/k8s] %s: core.worktree is set or unreadable (%q, %v), the renderers see the target only",
			target, strings.TrimSpace(string(worktree)), err)
		return targetOnly(target)
	}
	scope, ok := widerScope(target, strings.TrimSpace(string(out)))
	if !ok {
		return targetOnly(target)
	}
	log.Printf("[scan/k8s] renderers in a container mount %s, the repository holding %s", scope.mount, target)
	return scope
}

// gitEnviron is env without the variables that point git at another
// repository, work tree or configuration: the mount is decided by the target
// alone. GIT_CEILING_DIRECTORIES stays: it can only stop git's search for the
// repository earlier, and dropping it would widen what the user limited.
func gitEnviron(env []string) []string {
	out := make([]string, 0, len(env))
	for _, kv := range env {
		name, _, _ := strings.Cut(kv, "=")
		switch {
		case name == "GIT_DIR", name == "GIT_WORK_TREE", name == "GIT_COMMON_DIR",
			strings.HasPrefix(name, "GIT_CONFIG"):
			continue
		}
		out = append(out, kv)
	}
	return out
}

// widerScope mounts top, the repository git named, when it is safe to: top is
// a strict ancestor of the target once symlinks are resolved, neither the
// filesystem root nor the home directory nor anything above it, and it holds
// the repository's .git itself (gitDirIsHere). Anything else, an unknown home
// included, keeps the target alone.
func widerScope(target, top string) (renderScope, bool) {
	if top == "" || !filepath.IsAbs(top) {
		return renderScope{}, false
	}
	root, err := filepath.EvalSymlinks(top)
	if err != nil {
		return renderScope{}, false
	}
	real, err := filepath.EvalSymlinks(target)
	if err != nil {
		return renderScope{}, false
	}
	rel, err := filepath.Rel(root, real)
	if err != nil || rel == "." || rel == ".." || strings.HasPrefix(rel, ".."+string(filepath.Separator)) {
		return renderScope{}, false
	}
	if filepath.Dir(root) == root {
		return renderScope{}, false
	}
	home, err := userHomeDir()
	if err != nil || home == "" {
		return renderScope{}, false

	args = afterSubcommand(args, tool.Args)
	if tool.Source != ToolSourceContainer {
		name := tool.Binary
		if name == "" {
			name = binary
		}
		return toolCmd{Name: name, Args: args, Dir: scope.target}
	}
	return containerRun{
		Flags: []string{"-v", scope.mount + ":" + containerScanPath + ":ro", "-w", scope.workdir()},
		Image: orDefault(tool.Image, defaultImage),
		Argv:  args,
	}.cmd()
}

func orDefault(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

// renderRepro is the Repro line of a renderer run on target (a chart or an
// overlay directory), with the user's arguments where the scan put them: after
// the subcommand. Run from the scanned directory, like the scan did.
func renderRepro(tool ToolSpec, name, sub, target string) (string, ToolSource) {
	return localRepro(tool, name, afterSubcommand([]string{sub, target}, tool.Args)...)
}

func helmArgs(scope renderScope, chart string, tool ToolSpec, sub string) toolCmd {
	return renderer(scope, tool, DefaultHelmImage, "helm", sub, chart)
}

func kustomizeArgs(scope renderScope, dir string, tool ToolSpec) toolCmd {
	return renderer(scope, tool, DefaultKustomizeImage, "kustomize", "build", dir)
}
	if opts.CacheDir != "" {
		if err := os.MkdirAll(opts.CacheDir, 0o755); err != nil {
			// Validation still works without a cache; it downloads each time.
			opts.CacheDir = ""
		}
	}
	v := &k8sValidation{target: target, scope: targetOnly(target), kubeconform: tool, opts: opts,
		report: &KubeconformReport{Validated: len(layout.Manifests)}}
	// Only a renderer in a container needs more than the target mounted, and
	// git is asked only when one is about to run.
	if (len(layout.Charts) > 0 && opts.Helm.Source == ToolSourceContainer) ||
		(len(layout.Kustomizations) > 0 && opts.Kustomize.Source == ToolSourceContainer) {
		v.scope = resolveRenderScope(ctx, target)
	}

	if len(layout.Manifests) > 0 {
		if err := v.validateFiles(ctx, layout.Manifests, progressFn); err != nil {
			return nil, err
		}
	}
	if err := v.renderCharts(ctx, layout.Charts); err != nil {
		return nil, err
	}
	if err := v.renderKustomizations(ctx, layout.Kustomizations); err != nil {
		return nil, err
	}
	return v.report, nil
}

// validateFiles validates plain manifests, where each finding can be given the
// line its pointer designates.
func (v *k8sValidation) validateFiles(ctx context.Context, files []string, progressFn func(string)) error {
	cmd := kubeconformArgs(v.target, files, v.kubeconform, v.opts)
	log.Printf("Running: %s", cmd)
	out, err := runner.Run(ctx, cmd, progressFn)
	if err := kubeconformFailure(out, err); err != nil {
		return err
	}
	findings, skipped, err := parseKubeconformOutput(out, v.opts.KubernetesVersion, fileReader(v.target), nil)
	if err != nil {
		return err
	}
	v.stampSchemaRepro(findings)
	v.report.Findings = append(v.report.Findings, findings...)
	v.report.SkippedCustom += skipped
	return nil
}

// stampSchemaRepro records on each schema finding of a plain file where
// kubeconform ran and, when it ran on this machine, the command that checks that
// file again. DevDesk's own flags (-output json, -cache) are left out; the user's
// arguments stay where the scan put them. K8S-API-REMOVED and K8S-PARSE carry
// neither (DEVDESK-752).
func (v *k8sValidation) stampSchemaRepro(findings []Finding) {
	type reproLineFrom struct {
		line string
		from ToolSource
	}
	byFile := map[string]reproLineFrom{}
	for i := range findings {
		f := &findings[i]
		if f.ID != K8sSchemaID {
			continue
		}
		r, ok := byFile[f.File]
		if !ok {
			args := append(append([]string{}, v.kubeconform.Args...), "-strict")
			if v.opts.KubernetesVersion != "" {
				args = append(args, "-kubernetes-version", v.opts.KubernetesVersion)
			}
			r.line, r.from = localRepro(v.kubeconform, "kubeconform", append(args, f.File)...)
			byFile[f.File] = r
		}
		f.Repro, f.RanFrom = r.line, r.from
	}
}

// kubeconformFailure tells a run that found problems from one that failed.
// kubeconform exits 1 for both; what separates them is whether it wrote its
// JSON report.
func kubeconformFailure(out []byte, err error) error {
	if err == nil {
		return nil
	}
	var exitErr *exitError
	if errors.As(err, &exitErr) && exitErr.Code == 1 && looksLikeJSON(out) {
		return nil
	}
	return err
}

func looksLikeJSON(out []byte) bool {
	for _, b := range out {
		switch b {
		case ' ', '\n', '\r', '\t':
			continue
package scan

import (
	"errors"
	"os/exec"
	"testing"
)

// DEVDESK-752 (step 1): the Repro line is built from argv tokens, never quoted.
// A token a shell would read as more than a word refuses the whole line.

// useLookPath replaces the PATH lookup for one test: found maps a tool name to
// the binary it resolves to; any other name is not on PATH.
func useLookPath(t *testing.T, found map[string]string) {
	t.Helper()
	previous := lookPath
	lookPath = func(name string) (string, error) {
		if p, ok := found[name]; ok {
			return p, nil
		}
		return "", exec.ErrNotFound
	}
	t.Cleanup(func() { lookPath = previous })
}

// PlainWords is the one computation behind Run and Repro: it moved here from
// the finding detail, and its answers did not change.
func TestPlainWords(t *testing.T) {
	tests := []struct {
		name string
		cmd  string
		want bool
	}{
		{"words", "kustomize build kustomizations/dev", true},
		{"a flag with a value", "helm lint --set a=b charts/api", true},
		{"empty", "", true},
		{"a separator", "kustomize build a; rm -rf /", false},
		{"a pipe", "helm template x | kubeconform -", false},
		{"a variable", "cat $HOME", false},
		{"a quote", `echo "x"`, false},
		{"a backslash", `kubeconform C:\x`, false},
		{"a glob", "ls *.yaml", false},
		{"a tab", "a\tb", false},
		{"a line break", "a\nb", false},
		{"an escape sequence", "a\x1b[31mb", false},
		{"a zero-width space", "a\u200bb", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := PlainWords(tt.cmd); got != tt.want {
				t.Errorf("PlainWords(%q) = %v, want %v", tt.cmd, got, tt.want)
			}
		})
	}
}

func TestReproLine(t *testing.T) {
	tests := []struct {
		name    string
		program string
		args    []string
		want    string
		ok      bool
	}{
		{"the AC example", "kustomize", []string{"build", "kustomizations/dev"}, "kustomize build kustomizations/dev", true},
		{"no argument", "helm", nil, "helm", true},
		{"a flag with a value", "kubeconform", []string{"-kubernetes-version", "1.36.0", "deploy/app.yaml"},
			"kubeconform -kubernetes-version 1.36.0 deploy/app.yaml", true},
		{"a path with a space", "kustomize", []string{"build", "my overlay"}, "", false},
		{"a separator in an argument", "kustomize", []string{"build", "a;b"}, "", false},
		{"a tab in an argument", "kustomize", []string{"build", "x\ty"}, "", false},
		{"a control character", "kustomize", []string{"build", "x\x1b[0m"}, "", false},
		{"an empty argument", "kustomize", []string{"build", ""}, "", false},
		{"a Windows path", "kubeconform", []string{`C:\x`}, "", false},
		{"a program with a space", "/opt/my tools/helm", []string{"lint"}, "", false},
		{"an empty program", "", []string{"build"}, "", false},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, ok := reproLine(tt.program, tt.args...)
			if got != tt.want || ok != tt.ok {
				t.Errorf("reproLine(%q, %q) = (%q, %v), want (%q, %v)", tt.program, tt.args, got, ok, tt.want, tt.ok)
			}
		})
	}
}

// The plain tool name when PATH leads to the same binary: that is what a person
// would type. Any other binary keeps its configured path, which is what ran.
func TestReproProgram(t *testing.T) {
	found := func(path string, err error) func(string) (string, error) {
		return func(string) (string, error) { return path, err }
	}
	tests := []struct {
		name   string
		binary string
